update emp
username = #{username}, password = #{password}, name = #{name}, gender = #{gender}, phone = #{phone}, job = #{job}, salary = #{salary}, image = #{image}, entry_date = #{entryDate}, dept_id = #{deptId},
update_time = #{updateTime}
where id = #{id}

mapper.select:
select e.*, d.name as deptName from emp as e left join dept as d on e.dept_id = d.id
e.name like concat('%', #{name}, '%') and e.gender = #{gender} and e.entry_date between #{begin} and #{end}
order by e.update_time desc
